```python
def solve() -> None:
    s = input().strip()
    matching = {
        ')': '(',
        ']': '[',
        '}': '{'
    }
    stack = []

    for ch in s:
        if ch in '([{':
            stack.append(ch)
        else:
            if not stack or stack.pop() != matching.get(ch):
                print('NO')
                return

    print('YES' if not stack else 'NO')
```
